/**
 * Cursor-paginated scan history for a Member's public Profile, ordered
by `createdAt DESC`.

 * @summary Get a Profile's scan history page
 */
export const getGetProfileScansUrl = (
  username: string,
  params?: GetProfileScansParams,
) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    if (value !== undefined) {
      normalizedParams.append(key, value === null ? "null" : value.toString());
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0
    ? `/api/profiles/${username}/scans?${stringifiedParams}`
    : `/api/profiles/${username}/scans`;
};

export const getProfileScans = async (
  username: string,
  params?: GetProfileScansParams,
  options?: RequestInit,
): Promise<ProfileScansResponse> => {
  return customFetch<ProfileScansResponse>(
    getGetProfileScansUrl(username, params),
    {
      ...options,
      method: "GET",
    },
  );
};

